CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('FILMMAKER','NONFILMMAKER') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS festivals(id INT AUTO_INCREMENT PRIMARY KEY,admin_id INT NOT NULL,name VARCHAR(150) NOT NULL,deadline DATETIME NOT NULL,max_runtime_min INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(admin_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS rubric_criteria(id INT AUTO_INCREMENT PRIMARY KEY,festival_id INT NOT NULL,name VARCHAR(80) NOT NULL,weight INT NOT NULL,FOREIGN KEY(festival_id) REFERENCES festivals(id));
CREATE TABLE IF NOT EXISTS jury_requests(id INT AUTO_INCREMENT PRIMARY KEY,festival_id INT NOT NULL,user_id INT NOT NULL,status ENUM('PENDING','APPROVED') DEFAULT 'PENDING',UNIQUE(festival_id,user_id),FOREIGN KEY(festival_id) REFERENCES festivals(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS submissions(id INT AUTO_INCREMENT PRIMARY KEY,festival_id INT NOT NULL,filmmaker_id INT NOT NULL,title VARCHAR(150) NOT NULL,genre VARCHAR(60) NOT NULL,duration_min INT NOT NULL,synopsis TEXT NOT NULL,trailer_url VARCHAR(500) NOT NULL,film_url VARCHAR(500) NOT NULL,poster_file VARCHAR(100) NOT NULL,tracking_id VARCHAR(20) UNIQUE,status ENUM('PENDING_PAYMENT','INCOMPLETE','ELIGIBLE','INELIGIBLE') NOT NULL,reason VARCHAR(200),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(festival_id) REFERENCES festivals(id),FOREIGN KEY(filmmaker_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS assignments(id INT AUTO_INCREMENT PRIMARY KEY,submission_id INT NOT NULL,jury_id INT NOT NULL,UNIQUE(submission_id,jury_id));
CREATE TABLE IF NOT EXISTS scores(id INT AUTO_INCREMENT PRIMARY KEY,submission_id INT NOT NULL,jury_id INT NOT NULL,criterion_id INT NOT NULL,score INT NOT NULL,UNIQUE(submission_id,jury_id,criterion_id));
CREATE TABLE IF NOT EXISTS comments(id INT AUTO_INCREMENT PRIMARY KEY,submission_id INT NOT NULL,author_id INT NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS votes(id INT AUTO_INCREMENT PRIMARY KEY,festival_id INT NOT NULL,voter_id INT NOT NULL,submission_id INT NOT NULL,round INT NOT NULL DEFAULT 1,UNIQUE(festival_id,voter_id,round));
CREATE TABLE IF NOT EXISTS results(festival_id INT PRIMARY KEY,submission_id INT NOT NULL,override_reason VARCHAR(300),published_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,message VARCHAR(300) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_log(id INT AUTO_INCREMENT PRIMARY KEY,festival_id INT NOT NULL,admin_id INT NOT NULL,action VARCHAR(60) NOT NULL,detail VARCHAR(300),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)
